package com.aistock.gateway;
import com.sun.net.httpserver.HttpServer;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;
import feign.Feign;import org.springframework.cloud.openfeign.support.SpringMvcContract;import org.springframework.http.*;import com.fasterxml.jackson.databind.ObjectMapper;import com.aistock.common.ApiExceptionHandler;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;
class PortfolioQuestionProxyHttpTest {
 @Test void exactRoutesPreserveUserCredentialsAndErrorsWithoutTrustingIdentityHeaders()throws Exception{
  var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);var code=new AtomicInteger(201);var calls=new AtomicInteger();
  server.createContext("/api/v1/portfolio-questions",e->{calls.incrementAndGet();assertNull(e.getRequestHeaders().getFirst("X-User-Id"));assertNull(e.getRequestHeaders().getFirst("X-Service-Token"));assertEquals("AISTOCK_SESSION=synthetic",e.getRequestHeaders().getFirst("Cookie"));if(e.getRequestMethod().equals("POST")){assertEquals("{\"requestId\":\"fixture\"}",new String(e.getRequestBody().readAllBytes(),StandardCharsets.UTF_8));assertEquals("fixture-xsrf",e.getRequestHeaders().getFirst("X-XSRF-TOKEN"));}byte[] b="{\"code\":\"FIXTURE\",\"message\":\"fixture\",\"data\":null}".getBytes(StandardCharsets.UTF_8);e.getResponseHeaders().set("Content-Type","application/json");e.sendResponseHeaders(code.get(),b.length);e.getResponseBody().write(b);e.close();});server.start();
  try{var client=Feign.builder().contract(new SpringMvcContract()).client(new GatewayHttpConfiguration().userHttpClient()).options(new PortfolioQuestionClientConfiguration().portfolioQuestionOptions()).retryer(feign.Retryer.NEVER_RETRY).decoder((r,t)->ResponseEntity.status(r.status()).contentType(MediaType.APPLICATION_JSON).body(r.body().asInputStream().readAllBytes())).target(PortfolioQuestionPublicClient.class,"http://127.0.0.1:"+server.getAddress().getPort());
   var mvc=MockMvcBuilders.standaloneSetup(new PortfolioQuestionApiProxyController(client,new ObjectMapper())).setControllerAdvice(new ApiExceptionHandler()).build();
   mvc.perform(post("/api/v1/portfolio-questions").header("Cookie","AISTOCK_SESSION=synthetic").header("X-XSRF-TOKEN","fixture-xsrf").header("Origin","http://127.0.0.1:15173").header("X-User-Id","forged").header("X-Service-Token","forged").contentType("application/json").content("{\"requestId\":\"fixture\"}")).andExpect(status().isCreated()).andExpect(header().string("Cache-Control","no-store"));
   for(int status:new int[]{401,404,409,413,422,429}){code.set(status);mvc.perform(get("/api/v1/portfolio-questions").header("Cookie","AISTOCK_SESSION=synthetic")).andExpect(status().is(status)).andExpect(jsonPath("$.data").doesNotExist());}
   mvc.perform(post("/api/v1/portfolio-questions/arbitrary").content("{}")).andExpect(status().isNotFound());int before=calls.get();mvc.perform(get("/api/v1/portfolio-questions?userId=forged")).andExpect(status().isBadRequest());assertEquals(before,calls.get());
  }finally{server.stop(0);}
 }
 @Test void timeoutIsDedicatedAndInternalPathsRemainClosed(){var o=new PortfolioQuestionClientConfiguration().portfolioQuestionOptions();assertEquals(2000,o.connectTimeoutMillis());assertEquals(65000,o.readTimeoutMillis());assertFalse(o.isFollowRedirects());String base="/api/v1/portfolio-questions",id="33333333-3333-4333-8333-333333333333";assertTrue(ProxyHeaderPolicy.allowed("GET",base));assertTrue(ProxyHeaderPolicy.allowed("POST",base));assertTrue(ProxyHeaderPolicy.allowed("GET",base+"/"+id));assertTrue(ProxyHeaderPolicy.allowed("GET",base+"/operations/"+id));assertFalse(ProxyHeaderPolicy.allowed("POST",base+"/operations/"+id));assertFalse(ProxyHeaderPolicy.allowed("DELETE",base+"/"+id));assertFalse(ProxyHeaderPolicy.allowed("POST","/internal/v1/positions/snapshot"));}
 @Test void realNineSecondResponseIsNotCutOffByAnEightSecondBudget()throws Exception{
  var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/api/v1/portfolio-questions",e->{try{Thread.sleep(9000);byte[] b="{\"code\":\"OK\",\"data\":{}}".getBytes(StandardCharsets.UTF_8);e.sendResponseHeaders(200,b.length);e.getResponseBody().write(b);}catch(InterruptedException interrupted){Thread.currentThread().interrupt();}finally{e.close();}});server.start();
  try{var client=Feign.builder().contract(new SpringMvcContract()).client(new GatewayHttpConfiguration().userHttpClient()).options(new PortfolioQuestionClientConfiguration().portfolioQuestionOptions()).retryer(feign.Retryer.NEVER_RETRY).decoder((r,t)->ResponseEntity.status(r.status()).body(r.body().asInputStream().readAllBytes())).target(PortfolioQuestionPublicClient.class,"http://127.0.0.1:"+server.getAddress().getPort());var mvc=MockMvcBuilders.standaloneSetup(new PortfolioQuestionApiProxyController(client,new ObjectMapper())).setControllerAdvice(new ApiExceptionHandler()).build();long start=System.nanoTime();mvc.perform(get("/api/v1/portfolio-questions")).andExpect(status().isOk());assertTrue(System.nanoTime()-start>=java.util.concurrent.TimeUnit.MILLISECONDS.toNanos(8500));}finally{server.stop(0);}
 }
}
